<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/csrf.php';require_role(['Super Admin']);
$user=current_user();$error=$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='create'){ $name=trim($_POST['name']??'');$code=strtoupper(trim($_POST['code']??''));if($name&&$code){try{$pdo->prepare('INSERT INTO departments(name,code,mandatory,active) VALUES(?,?,1,1)')->execute([$name,$code]);audit_log($pdo,(int)$user['id'],'Super Admin','Created department',(int)$pdo->lastInsertId());$success='Department created.';}catch(PDOException $e){$error='Department code already exists.';}}else{$error='Name and code are required.';}
 }elseif($action==='toggle'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id){$pdo->prepare('UPDATE departments SET active=NOT active WHERE id=?')->execute([$id]);audit_log($pdo,(int)$user['id'],'Super Admin','Toggled department',$id);$success='Department status updated.';}}
}
$departments=$pdo->query('SELECT d.*,u.name hod_name FROM departments d LEFT JOIN users u ON u.id=d.hod_user_id ORDER BY d.name')->fetchAll();
$pageTitle='Manage Departments | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Super Admin</span></div><div class="avatar">SA</div></header><div class="content"><div class="page-header"><div><p>DEPARTMENT CONTROL</p><h1>Departments</h1></div></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?>
<section class="panel form-panel"><form method="post" class="inline-form" style="display:flex"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><input name="name" placeholder="Department name" required><input name="code" placeholder="Code" required><button class="btn btn-primary" type="submit">Add Department</button></form></section>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Code</th><th>HOD</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($departments as $d):?><tr><td><?=e($d['name'])?></td><td><?=e($d['code'])?></td><td><?=e($d['hod_name']?:'Unassigned')?></td><td><b class="status <?=$d['active']?'approved':'rejected'?>"><?=$d['active']?'Active':'Inactive'?></b></td><td><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$d['id']?>"><button class="action-btn" type="submit"><?=$d['active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
